import{_ as e,c as r,o as n,af as l,ag as a,ah as d,ai as s,aj as g,ak as i,al as o,am as c,an as x,ao as y}from"./chunks/framework.CI8A52oi.js";const u=JSON.parse('{"title":"关于酿酒","description":"","frontmatter":{},"headers":[],"relativePath":"brew.md","filePath":"brew.md"}'),p={name:"brew.md"};function h(m,t,b,_,k,f){return n(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="关于酿酒" tabindex="-1">关于酿酒 <a class="header-anchor" href="#关于酿酒" aria-label="Permalink to “关于酿酒”">​</a></h1><h2 id="煮制-发酵" tabindex="-1">煮制（发酵） <a class="header-anchor" href="#煮制-发酵" aria-label="Permalink to “煮制（发酵）”">​</a></h2><p><img src="'+a+'" alt=""></p><ol><li>如图，把炼药锅放在<strong>火或者其他热源</strong>上方</li><li>装满水</li><li><strong>通过右键添加原料</strong></li><li>等待原料发酵几分钟 (具体遵循酒谱时间<em>（单位min）</em>，会影响品质)</li><li>用玻璃瓶装起来</li></ol><p><em>tips:</em> <em>你可以使用时钟右键炼药锅查看以煮制时间</em></p><h2 id="蒸馏" tabindex="-1">蒸馏 <a class="header-anchor" href="#蒸馏" aria-label="Permalink to “蒸馏”">​</a></h2><p>蒸馏同样是十分关键的一环，蒸馏的方法也很简单</p><p>放置一个酿造台，蒸馏无需烈焰粉也可以进行，但请确保酿造台内放置了萤石粉</p><p><img src="'+d+'" alt=""></p><p><img src="'+s+'" alt=""></p><p><em>tips:</em> <em>萤石粉并不会被消耗，<strong>但它必须存在</strong></em></p><p><em>tips:</em> <em>有些配方不需要蒸馏。</em></p><h2 id="酒桶" tabindex="-1">酒桶 <a class="header-anchor" href="#酒桶" aria-label="Permalink to “酒桶”">​</a></h2><p>有些酒是需要放置在酒桶内陈酿的，最大陈酿年数为百年陈酿。</p><p>搭建一个酒桶并不需要过多的材料，不过也有着一些要求</p><p>使用不同木头所搭建出来的酒桶可以用于发酵不同的酒类</p><h3 id="木桶" tabindex="-1"><strong>木桶</strong> <a class="header-anchor" href="#木桶" aria-label="Permalink to “木桶”">​</a></h3><p>原版桶可以用来贮存少量饮品。 只要把桶放下来，往里面塞上需要贮存的饮品就行了</p><p><img src="'+g+'" alt=""></p><h3 id="小木桶" tabindex="-1"><strong>小木桶</strong> <a class="header-anchor" href="#小木桶" aria-label="Permalink to “小木桶”">​</a></h3><p>一个小木桶的搭建十分简单，这里我们以丛林木木桶为例:</p><blockquote><p>主体部分2x2x2</p></blockquote><p><img src="'+i+'" alt=""></p><p><img src="'+o+'" alt=""></p><p><em># 小木桶的存储空间小</em></p><p>在木桶的<strong>右下角</strong>放置一块告示牌并输入<code>barrel</code>来创建木桶</p><p>这时空手右键就可以打开</p><h3 id="大木桶" tabindex="-1">大木桶 <a class="header-anchor" href="#大木桶" aria-label="Permalink to “大木桶”">​</a></h3><blockquote><p>主题部分3x4x3，有四个栅栏脚</p></blockquote><p><img src="'+c+'" alt=""></p><p><img src="'+x+'" alt=""></p><p><em>将告示牌放置在酒桶的中上方，并输入&quot;barrel或BARREL&quot;来创建木桶</em></p><p>当聊天框提示” [Brewery]木桶已创建。“时木桶就已被成功创建</p><p>这时空手右键就可以打开</p><h3 id="封装台" tabindex="-1"><strong>封装台</strong> <a class="header-anchor" href="#封装台" aria-label="Permalink to “封装台”">​</a></h3><p>封装台是很重要的工具，你可以通过它把酒封装后放入酒桶内而不会影响品质</p><p><img src="'+y+'" alt=""></p><p><em>封装台的合成需要<strong>两个瓶子，四块木板</strong></em></p><p><em>将酒放入封装台，封装台将会自动封装</em></p><p><em>密封的饮品不能继续贮存或进一步加工，也不能显示详细信息</em></p><h2 id="饮用" tabindex="-1"><strong>饮用</strong> <a class="header-anchor" href="#饮用" aria-label="Permalink to “饮用”">​</a></h2><p>饮用时，饮品含有的酒精会持续累加在玩家身上。根据饮品质量的差异，可能产生不同的效果：</p><ul><li><em>无法正常行走，路线扭曲</em></li><li><em>失明、反胃、中毒等效果</em></li><li><em>聊天的内容会随醉酒情况改变，玩家写下的告示牌内容可能无法被理解，甚至无厘头</em></li><li><em>大量摄入酒精可能呕吐</em></li><li><em>酒后退出游戏，玩家在此后的短时间内可能无法进入游戏</em></li><li><em>过度饮酒后，玩家可能会晕倒（断开连接）</em></li></ul><h2 id="醒酒" tabindex="-1"><strong>醒酒</strong> <a class="header-anchor" href="#醒酒" aria-label="Permalink to “醒酒”">​</a></h2><p>喝完酒后需要一段时间才能完全清醒，在这段时间里，酒精含量会逐渐下降</p><p>也有一些饮品可以直接降低你的醉酒程度，例如 醒酒茶</p><p>如果你在严重喝醉的时候下线，你回来之后可能会发现自己在茫茫荒野中一个完全未知的地方。</p><p>但如果你在几小时后或第二天登录，会发现你回到了设置好的家中，失去了原来的记忆。</p><p>同样，如果饮品质量不算最好，你可能会遇到不好的宿醉类型（缓慢和饥饿）。</p><h2 id="图鉴" tabindex="-1"><strong>图鉴</strong> <a class="header-anchor" href="#图鉴" aria-label="Permalink to “图鉴”">​</a></h2><h3 id="尚存" tabindex="-1"><strong>尚存</strong> <a class="header-anchor" href="#尚存" aria-label="Permalink to “尚存”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">基础</th><th style="text-align:center;">酿造变种/中间态</th><th style="text-align:center;">酿造 (完美品质)</th></tr></thead><tbody><tr><td style="text-align:center;">粗制啤酒</td><td style="text-align:center;">啤酒</td><td style="text-align:center;"><strong>CORONA EXTRA</strong></td></tr><tr><td style="text-align:center;">淡红酒</td><td style="text-align:center;">红酒</td><td style="text-align:center;"><strong>透虹浪漫红酒</strong></td></tr><tr><td style="text-align:center;">淡葡萄酒</td><td style="text-align:center;">葡萄酒</td><td style="text-align:center;"><strong>映夜葡萄酒</strong></td></tr><tr><td style="text-align:center;">粗制蜂蜜酒</td><td style="text-align:center;">蜂蜜酒</td><td style="text-align:center;"><strong>双层蜜酒</strong></td></tr><tr><td style="text-align:center;">粗制威士忌</td><td style="text-align:center;">威士忌</td><td style="text-align:center;"><strong>尊尼获加</strong></td></tr><tr><td style="text-align:center;">淡咖啡</td><td style="text-align:center;">咖啡</td><td style="text-align:center;"><strong>Espresso</strong></td></tr><tr><td style="text-align:center;">暗淡金酒</td><td style="text-align:center;">金酒</td><td style="text-align:center;"><strong>代时金酒</strong></td></tr><tr><td style="text-align:center;">粗制朗姆</td><td style="text-align:center;">朗姆</td><td style="text-align:center;"><strong>沉润朗姆</strong></td></tr><tr><td style="text-align:center;">粗制伏特加</td><td style="text-align:center;">伏特加</td><td style="text-align:center;"><strong>Absolut Vodka</strong></td></tr><tr><td style="text-align:center;">粗制龙舌兰酒</td><td style="text-align:center;">龙舌兰酒</td><td style="text-align:center;"><strong>宾柔龙舌兰</strong></td></tr><tr><td style="text-align:center;">粗制苦艾酒</td><td style="text-align:center;">苦艾酒</td><td style="text-align:center;"><strong>留香苦艾酒</strong></td></tr><tr><td style="text-align:center;">浑浊蛋酒</td><td style="text-align:center;">蛋酒</td><td style="text-align:center;"><strong>泡泡蛋酒</strong></td></tr><tr><td style="text-align:center;">劣质蒲公英酒</td><td style="text-align:center;">蒲公英酒</td><td style="text-align:center;"><strong>三月雪</strong></td></tr><tr><td style="text-align:center;">发酵苹果汁</td><td style="text-align:center;">苹果酿</td><td style="text-align:center;"><strong>提神苹果佳酿</strong></td></tr><tr><td style="text-align:center;">浑浊葵花酒</td><td style="text-align:center;">蜜酿葵花酒</td><td style="text-align:center;"><strong>蜜液金花</strong></td></tr><tr><td style="text-align:center;">劣质黄油啤酒</td><td style="text-align:center;">黄油啤酒</td><td style="text-align:center;"><strong>暖意</strong></td></tr><tr><td style="text-align:center;">混合物</td><td style="text-align:center;">答辩水</td><td style="text-align:center;"><strong>腐殖之水</strong></td></tr><tr><td style="text-align:center;">劣质竹酒</td><td style="text-align:center;">竹酒</td><td style="text-align:center;"><strong>王竹瑞佑</strong></td></tr><tr><td style="text-align:center;">南瓜碎</td><td style="text-align:center;">南瓜汁</td><td style="text-align:center;"><strong>醇香南瓜汁</strong></td></tr><tr><td style="text-align:center;">浑浊玫瑰酒</td><td style="text-align:center;">玫瑰酒</td><td style="text-align:center;"><strong>红情一心</strong></td></tr><tr><td style="text-align:center;">工业废水</td><td style="text-align:center;">重金属蒸馏液</td><td style="text-align:center;"><strong>鎏金陈酿</strong></td></tr><tr><td style="text-align:center;">罗辑快乐酒</td><td style="text-align:center;">奇特的酒</td><td style="text-align:center;"><strong>沉船中的酒</strong></td></tr><tr><td style="text-align:center;">一瓶水晶</td><td style="text-align:center;">紫色悬浊液</td><td style="text-align:center;"><strong>碎晶花酿</strong></td></tr><tr><td style="text-align:center;">樱花甜酿</td><td style="text-align:center;">樱咲</td><td style="text-align:center;"><strong>Spring·Sakura·Sweet</strong></td></tr><tr><td style="text-align:center;">湛蓝之忆</td><td style="text-align:center;">瓦尔登蓝钻·含酒版</td><td style="text-align:center;"><strong>Sea = Azure</strong></td></tr><tr><td style="text-align:center;">假冒樱酒</td><td style="text-align:center;">粉霞</td><td style="text-align:center;"><strong>Sea = Pink</strong></td></tr><tr><td style="text-align:center;">灼红烈酒</td><td style="text-align:center;">海之血·夕烧</td><td style="text-align:center;"><strong>Sea = Red</strong></td></tr><tr><td style="text-align:center;">掺水伏特加</td><td style="text-align:center;">混沌伏特加</td><td style="text-align:center;"><strong>霜炙伏特加</strong></td></tr><tr><td style="text-align:center;">铃兰花茶</td><td style="text-align:center;">洁白森林的晨曦</td><td style="text-align:center;"><strong>无暇之春</strong></td></tr><tr><td style="text-align:center;">兰香</td><td style="text-align:center;">沼泽交响曲</td><td style="text-align:center;"><strong>红树·蓝花</strong></td></tr><tr><td style="text-align:center;">涩绿茶</td><td style="text-align:center;">绿茶</td><td style="text-align:center;"><strong>精制绿茶</strong></td></tr><tr><td style="text-align:center;">淡红茶</td><td style="text-align:center;">红茶</td><td style="text-align:center;"><strong>昏睡红茶（悲</strong></td></tr><tr><td style="text-align:center;"><strong>醒酒茶</strong></td><td style="text-align:center;">/</td><td style="text-align:center;">/</td></tr><tr><td style="text-align:center;"><strong>温水牛奶</strong></td><td style="text-align:center;">/</td><td style="text-align:center;">/</td></tr><tr><td style="text-align:center;"><strong>冰镇牛奶</strong></td><td style="text-align:center;">/</td><td style="text-align:center;">/</td></tr><tr><td style="text-align:center;"><strong>白色俄罗斯</strong></td><td style="text-align:center;">/</td><td style="text-align:center;">/</td></tr><tr><td style="text-align:center;"><strong>螺丝起子</strong></td><td style="text-align:center;">/</td><td style="text-align:center;">/</td></tr></tbody></table><h3 id="失落" tabindex="-1"><strong>失落</strong> <a class="header-anchor" href="#失落" aria-label="Permalink to “失落”">​</a></h3><table tabindex="0"><thead><tr><th>佳酿：小蛋糕</th><th>优醇：小蛋糕</th><th>国窖：小蛋糕</th></tr></thead><tbody><tr><td></td><td></td><td></td></tr></tbody></table>',54)])])}const S=e(p,[["render",h]]);export{u as __pageData,S as default};
